test('submitted text is planned with the shared credits, and a link, an over-long or an invisible-character name is refused', () => {
    const doc = project([asset(slotA, tags(shared)), asset(slotB, tags(shared))]);
    const submitted = planImportLookup(doc, { folderAvailable: true, submitted: { kind: 'album', text: '  Typed  Album ' } });
    assert.deepEqual(submitted.input, { trigger: 'submitted', submitted: { kind: 'album', text: '  Typed  Album ' } });
    assert.deepEqual(submitted.plan.queries.map(query => query.kind === 'musicBrainzReleaseSearch' ? query.query : null), [{ release: 'Typed Album', artist: 'Synthetic Ensemble' }, { release: 'Typed Album' }]);
    for (const [text, rejected] of [['https://example.test/album', 'url'], ['x'.repeat(201), 'tooLong'], ['Bell\u0007Album', 'invalidText'], ['Zero\u200bWidth', 'invalidText']] as const) {
        const plan = planImportLookup(doc, { folderAvailable: true, submitted: { kind: 'album', text } }).plan;
        assert.deepEqual([plan.queries, plan.rejected], [[], rejected], text);
    }
});

test('file names and folder segments other than a chosen root never reach a planned query', () => {
    let seed = 7;
    const random = () => { seed = (seed * 48271) % 2147483647; return seed.toString(36); };
    for (let round = 0; round < 40; round++) {
        const files = Array.from({ length: 1 + (round % 4) }, (_unused, index) => {
            const filename = `${random()}Secretfile${index}.flac`;
            return { slotId: `0000000b-0000-4000-a000-${String(round * 10 + index).padStart(12, '0')}`, filename, relativePath: `Root ${round}/Sub${random()}/${filename}`, byteLength: null };
        });
        const manifest: ImportManifest = { rootLabel: `Root ${round}`, files };
        const variants = [{}, shared, { title: 'Synthetic Song', artists: ['Synthetic Singer'] }];
        for (const extra of variants) {
            const doc = project(files.map(file => asset(file.slotId, tags(extra))), manifest);
            for (const options of [{ folderAvailable: true }, { folderAvailable: false }, { folderAvailable: true, submitted: { kind: 'song' as const, text: 'Typed Song' } }]) {
                const sent = JSON.stringify(planImportLookup(doc, options).plan.queries);
                for (const file of files) {
                    assert.equal(sent.includes(file.filename.replace(/\.flac$/, '')), false, file.filename);
                    assert.equal(sent.includes(file.relativePath.split('/')[1]), false, file.relativePath);
                }
            }
        }
    }
});

test('file evidence keeps manifest order, exact or legacy durations, draft Disc and Track Numbers, artist tags and identifiers', () => {
    const doc = project([
        asset(slotB, { title: 'Legacy', album: null, artists: ['Legacy Artist'], year: null, trackNumber: 2 }, { duration: '3:25' }),
        asset(slotA, tags({ durationMs: 390_266, artists: ['Synthetic Singer'], albumArtists: ['Synthetic Ensemble'] }, { musicBrainzReleaseId: releaseId(1), barcode: '0075596050920', catalogNumber: 'SYN-001' }))]);
    const draft = doc.draft as ReturnType<typeof defaultDraftV2>;
    draft.tracks[0].discNumber = 1; draft.tracks[0].trackNumber = 1; draft.tracks[1].trackNumber = 2;
    assert.deepEqual(lookupFileEvidence(doc), [
        { slotId: slotA, order: 0, durationMs: 390_266, durationPrecisionMs: 0, discNumber: 1, trackNumber: 1, artistTags: ['Synthetic Singer', 'Synthetic Ensemble'],
            identifiers: { releaseId: releaseId(1), barcode: '0075596050920', catalogNumber: 'SYN-001' } },
        // Legacy evidence contributes only its stored mm:ss duration, with one-second precision.
        { slotId: slotB, order: 1, durationMs: 205_000, durationPrecisionMs: 1000, discNumber: null, trackNumber: 2, artistTags: [],
            identifiers: { releaseId: null, barcode: null, catalogNumber: null } }]);
    // An unconfirmed file has no duration and no tags.
    assert.deepEqual(lookupFileEvidence(project([asset(slotA, tags({ durationMs: 1000 }), { state: 'pending' })]))[0], { slotId: slotA, order: 0, durationMs: null, durationPrecisionMs: 0,
        discNumber: null, trackNumber: null, artistTags: [], identifiers: { releaseId: null, barcode: null, catalogNumber: null } });
});

test('shared release IDs and catalogue numbers are usable tags of several files, while an ISRC counts only for one file', () => {
    const release = '24ae881f-7cb3-4c43-b80e-70332cd7c50d';
    const both = (extra: Record<string, unknown>, identifiers: Record<string, unknown>) => project([asset(slotA, tags(extra, identifiers)), asset(slotB, tags(extra, identifiers))]);
    const byId = planImportLookup(both(shared, { musicBrainzReleaseId: release, catalogNumber: 'SYN-001', isrc: 'JPY392200483' }), { folderAvailable: true });
    assert.deepEqual([byId.input.trigger, byId.plan.queries.map(query => [query.kind, query.basis])], ['tags', [
        ['musicBrainzRelease', 'releaseId'], ['musicBrainzReleaseSearch', 'catalogNumber'], ['musicBrainzReleaseSearch', 'albumText'], ['musicBrainzReleaseSearch', 'albumText']]]);
    assert.equal((byId.plan.queries[0] as { releaseId: string }).releaseId, release);
    // An ISRC is a recording's: several files never send one, and without other usable tags the folder name is used instead.
    const isrcOnly = planImportLookup(both({}, { isrc: 'JPY392200483' }), { folderAvailable: true });
    assert.deepEqual([isrcOnly.input.trigger, isrcOnly.plan.queries.every(query => query.basis === 'folder')], ['folder', true]);
    // A stored identifier that is not in its normalized format is not usable.
    for (const musicBrainzReleaseId of ['not-an-mbid', release.toUpperCase()]) assert.equal(planImportLookup(both({}, { musicBrainzReleaseId }), { folderAvailable: false }).plan.queries.length, 0);
    // A project without media has no confirmed file, so nothing is shared and the file set binds nulls.
    const empty = project([]); delete (empty as { media?: unknown }).media;
    assert.deepEqual([importLookupFileSet(empty).complete, importLookupFileSet(empty).files.map(file => file.operationId)], [false, [null, null]]);
});

test('lookup accepts only a writable Draft v2 import project that no publication locks and that has not completed', () => {
    const publication = (state: string, cleanupPending = false) => ({ media: { assets: [], publication: { state, cleanupPending } } }) as unknown as Partial<AdminImportDocument>;
    assert.equal(metadataLookupAccepted(project([])), true);
    // A cancelled publication without pending cleanup no longer locks the sources.
    assert.equal(metadataLookupAccepted(project([], folderManifest, publication('cancelled'))), true);
    const refused: [string, Partial<AdminImportDocument>][] = [
        ['catalog review', { purpose: 'catalogReview' }], ['legacy format', { draftVersion: 1 } as Partial<AdminImportDocument>],
        ['newer format', { draftVersion: 3 } as unknown as Partial<AdminImportDocument>], ['applied review', { catalogApplied: { operationId: slotA, at: '2026-10-19T00:00:00.000Z', fields: [] } }],
        ['preparing', publication('preparing')], ['needs attention', publication('needsAttention')], ['cancelled with cleanup pending', publication('cancelled', true)],
        ['complete', publication('complete')], ['malformed draft', { draft: { album: {} } as unknown as AdminImportDocument['draft'] }]
    ];
    for (const [label, extra] of refused) assert.equal(metadataLookupAccepted(project([], folderManifest, extra)), false, label);
});

test('candidates are distinct after normalization, capped at 25 in a stable order, and a release found by ID is fetched', () => {
    const release = releases[0];
    let candidates = mergeLookupCandidates([], [{ releaseId: release.releaseId.toUpperCase(), release }], 'releaseId');
    assert.deepEqual(candidates.map(candidate => [candidate.key, candidate.releaseId, candidate.details, candidate.basis]), [[`musicbrainz:${release.releaseId}`, release.releaseId, 'fetched', 'releaseId']]);
    const found = [{ releaseId: release.releaseId }, { releaseId: 'not-an-mbid' }, ...Array.from({ length: 30 }, (_unused, index) => ({ releaseId: releaseId(index) })), { releaseId: releaseId(0) }];
    candidates = mergeLookupCandidates(candidates, found, 'albumText');
    assert.equal(candidates.length, METADATA_LOOKUP_JOB_LIMITS.candidates);
    assert.deepEqual(candidates.slice(1).map(candidate => [candidate.releaseId, candidate.details, candidate.summary, candidate.release]),
        Array.from({ length: 24 }, (_unused, index) => [releaseId(index), 'pending', null, null]));
    // A full list takes nothing more and keeps its order.
    assert.deepEqual(mergeLookupCandidates(candidates, [{ releaseId: releaseId(99) }], 'folder'), candidates);
});

test('admission prefers releases whose reported track count can match the files, and a search is complete only when every offered release that could match was admitted', () => {
    assert.deepEqual([lookupTrackCountPlausible(9, 9), lookupTrackCountPlausible(19, 9), lookupTrackCountPlausible(0, 9), lookupTrackCountPlausible(undefined, 9),
        lookupTrackCountPlausible(null, 9), lookupTrackCountPlausible(2.5, 9), lookupTrackCountPlausible('9', 9)], [true, false, true, true, true, true, true]);
    const summary = (index: number, trackCount: number) => ({ releaseId: releaseId(index), summary: { trackCount } as never });
    // 30 offered releases, the implausible ones first: the 25 admitted are every plausible one, then implausible ones in their order.
    const found = [...Array.from({ length: 10 }, (_unused, index) => summary(index, 19)), ...Array.from({ length: 20 }, (_unused, index) => summary(10 + index, 9))];
    const merged = mergeLookupCandidates([], found, 'albumText', 9);
    assert.deepEqual(merged.map(candidate => candidate.releaseId), [...Array.from({ length: 20 }, (_unused, index) => releaseId(10 + index)), ...Array.from({ length: 5 }, (_unused, index) => releaseId(index))]);
    // The five left out report 19 tracks, so they cannot match nine files: the search stays complete. One plausible or unknown one more is not.
    assert.equal(lookupHitsAdmitted(merged, found, 9), true);
    assert.equal(lookupHitsAdmitted(merged, [...found, summary(50, 9)], 9), false);
    assert.equal(lookupHitsAdmitted(merged, [...found, { releaseId: releaseId(51) }], 9), false);
    assert.equal(lookupHitsAdmitted(merged, found, 19), false, 'for nineteen files the left-out releases could match');
    // Without a file count, the found order is kept; a recording hit's release (no summary) keeps the count it reported.
    assert.deepEqual(mergeLookupCandidates([], found, 'albumText').map(candidate => candidate.releaseId), found.slice(0, 25).map(item => item.releaseId));
    const recordingHits = [{ releaseId: releaseId(40), trackCount: 15 }, { releaseId: releaseId(41), trackCount: null }, { releaseId: releaseId(42), trackCount: 1 }];
    const songs = mergeLookupCandidates([], recordingHits, 'songText', 1);
    assert.deepEqual(songs.map(candidate => [candidate.releaseId, candidate.reportedTrackCount, lookupReportedTrackCount(candidate)]),
        [[releaseId(41), undefined, null], [releaseId(42), 1, 1], [releaseId(40), 15, 15]]);
    assert.equal(lookupHitsAdmitted(songs, recordingHits, 1), true);
    // A summary's count is not stored twice; an invalid reported count is unknown.
    assert.deepEqual(mergeLookupCandidates([], [{ ...summary(60, 9), trackCount: 3 }, { releaseId: releaseId(61), trackCount: -2 }], 'albumText', 9)
        .map(candidate => [candidate.reportedTrackCount, lookupReportedTrackCount(candidate)]), [[undefined, 9], [undefined, null]]);
    // Invalid IDs are never candidates and never make a search partial; an already-known release counts as admitted.
    assert.equal(lookupHitsAdmitted(merged, [{ releaseId: 'not-an-mbid' }, { releaseId: releaseId(10).toUpperCase() }], 9), true);
});

test('details record missing, failed and compact fetched releases, and a release over the byte budget is omitted', () => {
    const withIsrcs = releases.find(release => release.media.some(medium => medium.tracks.some(track => track.isrcs.length)))!;
    let candidates = mergeLookupCandidates([], [{ releaseId: withIsrcs.releaseId }, { releaseId: releaseId(1) }, { releaseId: releaseId(2) }], 'albumText');
    candidates = recordLookupDetails(candidates, withIsrcs.releaseId.toUpperCase(), withIsrcs);
    candidates = recordLookupDetails(candidates, releaseId(1), null);
    candidates = recordLookupDetails(candidates, releaseId(2), 'failed');
    assert.deepEqual(candidates.map(candidate => candidate.details), ['fetched', 'missing', 'failed']);
    assert.ok(candidates[0].release!.media.every(medium => medium.tracks.every(track => track.isrcs.length === 0)));
    assert.deepEqual({ ...candidates[0].release!, media: [] }, { ...withIsrcs, media: [] });
    assert.deepEqual([candidates[1].release, candidates[2].release], [null, null]);
    // An unknown release ID changes nothing.
    assert.deepEqual(recordLookupDetails(candidates, releaseId(9), 'failed'), candidates);
    const huge: MusicBrainzRelease = { ...withIsrcs, releaseId: releaseId(3), media: [{ position: 1, format: null,
        tracks: Array.from({ length: 4500 }, (_unused, index) => ({ position: index + 1, number: String(index + 1), title: 'x'.repeat(1000), lengthMs: null, recordingId: releaseId(4), isrcs: [] })) }] };
    const budget = recordLookupDetails(mergeLookupCandidates(candidates, [{ releaseId: huge.releaseId }], 'albumText'), huge.releaseId, huge);
    assert.deepEqual([budget[3].details, budget[3].release], ['omitted', null]);
    assert.equal(mergeLookupCandidates(candidates, [{ releaseId: huge.releaseId, release: huge }], 'releaseId')[3].details, 'omitted');
});

test('ranking a record compares stored candidates with the current files and leaves incomplete ones unranked', () => {
    const base = releases.find(release => release.releaseId.startsWith('24ae881f'))!;
    const manifest: ImportManifest = { rootLabel: '', files: base.media[0].tracks.map((_track, index) => ({ slotId: `0000000c-0000-4000-a000-${String(index).padStart(12, '0')}`, filename: `${index}.flac`, relativePath: `${index}.flac`, byteLength: null })) };
    const doc = project(manifest.files.map((file, index) => asset(file.slotId, tags({ durationMs: base.media[0].tracks[index].lengthMs }))), manifest);
    const candidates: StoredLookupCandidate[] = mergeLookupCandidates([], [{ releaseId: base.releaseId, release: base }, { releaseId: releaseId(5) }], 'albumText');
    const now = new Date('2026-10-19T00:00:00Z'), ranking = rankLookupRecord(candidates, doc, now, { searchComplete: true });
    assert.deepEqual([ranking.rankedAt, ranking.files.length, ranking.candidates.map(candidate => [candidate.releaseId, candidate.status])],
        [now, 9, [[base.releaseId, 'matching'], [releaseId(5), 'incomplete']]]);
    // The incomplete candidate might match too: the comparison is partial, so the one matching group is not preselected.
    assert.deepEqual([ranking.preselection, ranking.disclosure.partialComparison], [null, true]);
    // An incomplete candidate that cannot match hides nothing: a release that no longer exists (404), or one whose search or
    // recording hit reported another track count, whether its details failed or were omitted.
    const cannotMatch: StoredLookupCandidate[] = [candidates[0], recordLookupDetails(candidates, releaseId(5), null)[1],
        { ...candidates[1], key: `musicbrainz:${releaseId(6)}`, releaseId: releaseId(6), summary: { trackCount: 3 } as never, details: 'failed' },
        { ...candidates[1], key: `musicbrainz:${releaseId(7)}`, releaseId: releaseId(7), reportedTrackCount: 12, details: 'omitted' }];
    const kept = rankLookupRecord(cannotMatch, doc, now, { searchComplete: true });
    assert.deepEqual([cannotMatch.map(candidate => candidate.details), kept.disclosure.partialComparison, kept.preselection?.basis],
        [['fetched', 'missing', 'failed', 'omitted'], false, 'onlyMatchingGroup']);
    const unknown = rankLookupRecord([...cannotMatch, { ...candidates[1], key: `musicbrainz:${releaseId(8)}`, releaseId: releaseId(8), reportedTrackCount: 9, details: 'failed' }], doc, now, { searchComplete: true });
    assert.deepEqual([unknown.disclosure.partialComparison, unknown.preselection], [true, null], 'one reporting the files\' track count could match');
    const fetched = candidates.slice(0, 1);
    assert.equal(rankLookupRecord(fetched, doc, now, { searchComplete: true }).preselection?.candidateKey, `musicbrainz:${base.releaseId}`);
    const partial = rankLookupRecord(fetched, doc, now, { searchComplete: false });
    assert.deepEqual([partial.groups.length, partial.preselection, partial.disclosure.partialComparison], [1, null, true]);
});

test('candidates and ranking together stay within the record budget by omitting the largest fetched releases', () => {
    const base = releases.find(release => release.releaseId.startsWith('24ae881f'))!;
    const manifest: ImportManifest = { rootLabel: '', files: base.media[0].tracks.map((_track, index) => ({ slotId: `0000000c-0000-4000-a000-${String(index).padStart(12, '0')}`, filename: `${index}.flac`, relativePath: `${index}.flac`, byteLength: null })) };
    const doc = project(manifest.files.map((file, index) => asset(file.slotId, tags({ durationMs: base.media[0].tracks[index].lengthMs }))), manifest);
    // The same tracklist with long titles: it matches too, forms its own group and is the largest release.
    const long: MusicBrainzRelease = { ...base, releaseId: releaseId(6), media: base.media.map(medium => ({ ...medium, tracks: medium.tracks.map(track => ({ ...track, title: 'x'.repeat(2000) })) })) };
    const candidates = mergeLookupCandidates([], [{ releaseId: base.releaseId, release: base }, { releaseId: long.releaseId, release: long }], 'albumText');
    const now = new Date('2026-10-19T00:00:00Z'), bytes = (value: unknown) => Buffer.byteLength(JSON.stringify(value));
    const roomy = rankLookupWithinBudget(candidates, doc, now, { searchComplete: true });
    assert.deepEqual([roomy.candidates, roomy.ranking], [candidates, rankLookupRecord(candidates, doc, now, { searchComplete: true })]);
    assert.equal(roomy.ranking.groups.length, 2);
    // Just too small for both: only the largest release is omitted, and the rest is ranked again. The omitted release matched as
    // its own group, so the comparison is partial and the remaining group is not preselected.
    const trimmed = candidates.map((candidate, index) => index === 1 ? { ...candidate, release: null, details: 'omitted' as const } : candidate);
    const fits = bytes({ candidates: trimmed, ranking: rankLookupRecord(trimmed, doc, now, { searchComplete: true }) });
    const bounded = rankLookupWithinBudget(candidates, doc, now, { searchComplete: true, budget: fits });
    assert.deepEqual([bounded.candidates.map(candidate => candidate.details), bounded.ranking.candidates.map(candidate => candidate.status), bounded.ranking.groups.length,
        bounded.ranking.preselection, bounded.ranking.disclosure.partialComparison], [['fetched', 'omitted'], ['matching', 'incomplete'], 1, null, true]);
    assert.ok(bytes(bounded) <= fits);
    // An incomplete search is passed through every re-rank.
    assert.equal(rankLookupWithinBudget(candidates, doc, now, { searchComplete: false }).ranking.disclosure.partialComparison, true);
    // A budget nothing fits leaves every candidate incomplete and nothing preselected.
    const none = rankLookupWithinBudget(candidates, doc, now, { searchComplete: true, budget: 0 });
    assert.deepEqual([none.candidates.map(candidate => candidate.details), none.ranking.preselection], [['omitted', 'omitted'], null]);
});

test('ranking reads the iTunes localized names and the check of each iTunes-only candidate; an iTunes-only candidate is admitted once, within the shared bound', () => {
    const base = releases.find(release => release.releaseId.startsWith('24ae881f'))!;
    const manifest: ImportManifest = { rootLabel: '', files: base.media[0].tracks.map((_track, index) => ({ slotId: `0000000c-0000-4000-a000-${String(index).padStart(12, '0')}`, filename: `${index}.flac`, relativePath: `${index}.flac`, byteLength: null })) };
    const doc = project(manifest.files.map((file, index) => asset(file.slotId, tags({ durationMs: base.media[0].tracks[index].lengthMs, artists: ['イーグルス'] }))), manifest);
    const now = new Date('2026-10-19T00:00:00Z'), [candidate] = mergeLookupCandidates([], [{ releaseId: base.releaseId, release: base }], 'albumText');
    // The artist tag shows the jp storefront's name; the run's localized group links it to the credited name.
    assert.deepEqual([rankLookupWithinBudget([candidate], doc, now, { searchComplete: true }).ranking.preselection?.artistMismatch,
        rankLookupWithinBudget([candidate], doc, now, { searchComplete: true, localized: [['Eagles', 'イーグルス']] }).ranking.preselection?.artistMismatch], [true, false]);
    // The same values as an iTunes-only candidate rank by its check: one the bridge did not run for is never preselected.
    const itunes = (check: 'noRelease' | 'notRun'): StoredLookupCandidate => ({ key: 'itunes:635770200', source: 'itunes', releaseId: '635770200', basis: 'itunes', summary: null,
        release: { ...base, releaseId: '635770200' }, details: 'fetched', itunes: { storefront: 'us', artworkUrl: null, check } });
    assert.deepEqual([rankLookupRecord([itunes('noRelease')], doc, now, { searchComplete: true }).preselection?.candidateKey, rankLookupRecord([itunes('notRun')], doc, now, { searchComplete: true }).preselection],
        ['itunes:635770200', null]);
    assert.deepEqual(admitItunesCandidate([candidate], itunes('noRelease'))!.map(item => [item.key, item.details]), [[candidate.key, 'fetched'], ['itunes:635770200', 'fetched']]);
    assert.deepEqual(admitItunesCandidate([itunes('notRun')], itunes('noRelease')), [itunes('notRun')]);
    const full = Array.from({ length: METADATA_LOOKUP_JOB_LIMITS.candidates }, () => candidate);
    assert.equal(admitItunesCandidate(full, itunes('noRelease')), null);
    // One whose collection lookup gave no complete release is admitted without one: incomplete, and partial while it could match.
    const short: StoredLookupCandidate = { ...itunes('noRelease'), release: null, details: 'omitted', reportedTrackCount: base.media[0].tracks.length };
    const admitted = admitItunesCandidate([], short)!, ranked = rankLookupRecord(admitted, doc, now, { searchComplete: true });
    assert.deepEqual([admitted.map(item => [item.key, item.details, item.release]), ranked.candidates.map(item => item.status), ranked.disclosure.partialComparison, ranked.preselection],
        [[['itunes:635770200', 'omitted', null]], ['incomplete'], true, null]);
    assert.equal(admitItunesCandidate(full, short), null);
});

test('automatic retries run after 30 seconds, 2 minutes and 5 minutes, or a longer Retry-After of at most a minute, then stop; a first 503/429 within seconds', () => {
    const now = new Date('2026-10-19T00:00:00Z'), at = (failures: number, retryAfterMs: number | null = null) => lookupRetryAt(failures, now, retryAfterMs)?.getTime() ?? null;
    const limited = (failures: number, retryAfterMs: number | null = null) => lookupRetryAt(failures, now, retryAfterMs, { rateLimited: true })?.getTime() ?? null;
    // A throttled first attempt follows its Retry-After within 2 to 10 seconds (2 seconds without one), later ones the schedule.
    assert.deepEqual([limited(1), limited(1, 1000), limited(1, 7000), limited(1, 45_000), limited(1, NaN), limited(1, -5000), limited(1, Infinity)],
        [2_000, 2_000, 7_000, 10_000, 2_000, 2_000, 2_000].map(delay => now.getTime() + delay));
    assert.deepEqual([limited(2, 1000), limited(3, 1000), limited(4, 1000), limited(0)], [now.getTime() + 120_000, now.getTime() + 300_000, null, null]);
    assert.deepEqual([at(1), at(2), at(3), at(4), at(0)], [now.getTime() + 30_000, now.getTime() + 120_000, now.getTime() + 300_000, null, null]);
    assert.deepEqual([at(1, 45_000), at(1, 5_000)], [now.getTime() + 45_000, now.getTime() + 30_000]);
    // A Retry-After counts for at most a minute; a negative or non-finite one counts as none.
    assert.deepEqual([at(1, 600_000), at(3, 600_000), at(1, Number.MAX_VALUE), at(1, Infinity), at(1, NaN), at(1, -60_000)],
        [now.getTime() + 60_000, now.getTime() + 300_000, now.getTime() + 60_000, now.getTime() + 30_000, now.getTime() + 30_000, now.getTime() + 30_000]);
});

test('every fence write increments from absent, and only queued, running and retrying runs block', () => {
    const states: MetadataLookupState[] = ['queued', 'running', 'retrying', 'complete', 'unavailable', 'stopped', 'superseded'];
    assert.deepEqual(states.filter(isBlockingLookupState), ['queued', 'running', 'retrying']);
    const first = lookupGateFor({ run: 1, state: 'queued' });
    assert.deepEqual(first, { fence: 1, run: 1, state: 'queued', blocking: true });
    assert.deepEqual(lookupGateFor({ run: 1, state: 'queued' }, first), { fence: 2, run: 1, state: 'queued', blocking: true });
    assert.deepEqual(lookupGateFor({ run: 2, state: 'complete' }, { fence: -4, run: 1, state: 'queued', blocking: true }), { fence: 1, run: 2, state: 'complete', blocking: false });
});

test('a new run replaces the previous results and carries only the automatic count, folder use and applied values', () => {
    const now = new Date('2026-10-19T00:00:00Z'), fileSet = importLookupFileSet(project([asset(slotA, null), asset(slotB, null)]));
    const query = { kind: 'musicBrainzReleaseSearch' as const, query: { release: 'Synthetic Album' }, basis: 'albumText' as const };
    const init = { importId: new ObjectId(importId), actorId: '0000000000000000000000e1', grantSource: 'upload' as const, operationId: automaticLookupOperationId(importId, 1, fileSet.digest),
        automatic: true, input: { trigger: 'folder' as const, submitted: null }, queries: [query], fileSet, now };
    // Planning a folder run spends nothing: only the worker's step that hands out a folder query does.
    const first = startLookupRun(null, init);
    assert.deepEqual([first.run, first.state, first.phase, first.outcome, first.automaticRuns, first.folderUsed, first.grantExpiresAt.getTime() - now.getTime(), first.fileSetDigest, first.files,
        first.searchComplete], [1, 'queued', 'search', null, 1, false, METADATA_LOOKUP_JOB_LIMITS.grantMs, fileSet.digest, fileSet.files, true]);
    assert.equal(startLookupRun(first, init).folderUsed, false);
    const applied: MetadataLookupRecord['applied'] = { run: 1, candidateKey: `musicbrainz:${releaseId(1)}`, releaseId: releaseId(1), choice: 'preselected', basis: 'onlyMatchingGroup',
        actorId: '0000000000000000000000e1', operationId: null, at: now, paths: ['album.title'], values: [{ path: 'album.title', value: 'Synthetic Album', slotId: null }], conflicts: [], flagged: [] };
    const previous: MetadataLookupRecord = { ...first, state: 'complete', candidates: mergeLookupCandidates([], [{ releaseId: releaseId(1) }], 'albumText'), staleSlotIds: [slotA], applied,
        attempts: { musicbrainz: 2 }, queryIndex: 1, folderUsed: true, searchComplete: false };
    // A run starts with no alias lookups; a previous run's aliases never carry over.
    assert.deepEqual(first.aliases, []);
    const second = startLookupRun({ ...previous, aliases: [{ kind: 'artist', id: releaseId(9), state: 'fetched', names: ['Old'] }] },
        { ...init, automatic: false, grantSource: 'submit', queries: [], input: { trigger: 'submitted', submitted: { kind: 'album', text: 'x' } } });
    assert.deepEqual(second.aliases, []);
    assert.deepEqual([...lookupFetchedAliases({ aliases: [{ kind: 'artist', id: releaseId(9), state: 'fetched', names: ['A', 7 as never] }, { kind: 'label', id: releaseId(8), state: 'failed', names: ['B'] },
        { kind: 'artist', id: 'bad', state: 'fetched', names: ['C'] }, null as never] })], [[releaseId(9), ['A']]]);
    assert.deepEqual([...lookupFetchedAliases({}), ...lookupFetchedAliases(null)], []);
    assert.deepEqual([second.run, second.state, second.phase, second.outcome, second.completedAt, second.automaticRuns, second.folderUsed, second.applied, second.candidates, second.staleSlotIds, second.attempts, second.queryIndex,
        second.searchComplete], [2, 'complete', 'done', 'noQuery', now, 1, true, applied, [], [], { musicbrainz: 0, itunes: 0 }, 0, true]);
    // The previous run's iTunes stage, iTunes attempts and exhausted sources never carry over.
    const third = startLookupRun({ ...previous, attempts: { musicbrainz: 2, itunes: 3 }, exhausted: { musicbrainz: 'sourceUnavailable', itunes: 'sourceBusy' },
        itunesStage: { reason: 'noMatch', text: null, requests: [], requestIndex: 0, items: [], bridge: [], bridgeIndex: 0, bridgeOutcomes: [], state: 'answered', complete: false, finalized: true } }, init);
    assert.deepEqual([third.attempts, third.exhausted, third.itunesStage], [{ musicbrainz: 0, itunes: 0 }, {}, null]);
    const later = new Date(now.getTime() + 1000), granted = refreshLookupGrant(first, '0000000000000000000000e2', 'choose', later);
    assert.deepEqual([granted.actorId, granted.grantSource, granted.grantExpiresAt.getTime(), granted.run, granted.state], ['0000000000000000000000e2', 'choose', later.getTime() + METADATA_LOOKUP_JOB_LIMITS.grantMs, 1, 'queued']);
});

test('an automatic run intent is deterministic and UUID-shaped', () => {
    const id = automaticLookupOperationId(importId, 2, 'a'.repeat(64));
    assert.equal(id, automaticLookupOperationId(importId, 2, 'a'.repeat(64)));
    assert.equal(uuid(id), true);
    assert.notEqual(id, automaticLookupOperationId(importId, 3, 'a'.repeat(64)));
    assert.notEqual(id, automaticLookupOperationId(importId, 2, 'b'.repeat(64)));
});

test('the worker is idle without reaching the database while imports are disabled or it is stopping, and stops cleanly', async () => {
    assert.equal(process.env.FINITUDE_ADMIN_IMPORTS_ENABLED, 'false');
    assert.equal(await runMetadataLookupOnce(), false);
    const stopped = new AbortController(); stopped.abort();
    process.env.FINITUDE_ADMIN_IMPORTS_ENABLED = 'true';
    try {
        assert.equal(await runMetadataLookupOnce({}, stopped.signal), false);
        // Enabled and not stopping, it reaches the (unconnected) database: the checks above are what kept it away.
        await assert.rejects(runMetadataLookupOnce({}), TypeError);
    } finally { process.env.FINITUDE_ADMIN_IMPORTS_ENABLED = 'false'; }
    let tracked = 0;
    const stop = startMetadataLookupWorker({}, 5, async operation => { tracked++; return operation(); });
    await new Promise(resolve => setTimeout(resolve, 20));
    await stop();
    assert.ok(tracked >= 1);
});
